export default "SELECT DISTINCT\n    TAB_CLIENTE.COD_CLIENTE,\n    TAB_CLIENTE.DES_CLIENTE,\n    TAB_CLIENTE.NUM_CGC,\n    TAB_CLIENTE.NUM_INSC_EST,\n    TAB_CLIENTE.DES_ENDERECO,\n    TAB_CLIENTE.DES_BAIRRO,\n    TAB_CIDADE.DES_CIDADE,\n    TAB_CIDADE.DES_SIGLA,\n    TAB_CLIENTE.NUM_CEP,\n    TAB_CLIENTE.NUM_FONE,\n    TAB_CLIENTE.NUM_FAX,\n    TAB_CLIENTE.NUM_CELULAR,\n    TAB_CLIENTE.DES_CONTATO,\n    TAB_CLIENTE.FLG_SEXO,\n    TAB_CLIENTE.VAL_LIMITE_CONV,\n    TAB_CLIENTE.VAL_LIMITE_CREDITO AS VAL_LIMITE_CRETID,\n    TAB_CLIENTE.COD_CONVENIO,\n    TAB_CLIENTE.COD_STATUS_PDV,\n    TAB_CLIENTE.FLG_EMPRESA,\n    TAB_CLIENTE.FLG_CONVENIO,\n    TAB_CLIENTE.MICRO_EMPRESA,\n    TAB_CLIENTE.DTA_CADASTRO,\n    TAB_CLIENTE.NUM_ENDERECO,\n    TAB_CLIENTE.NUM_RG,\n    TAB_CLIENTE.FLG_EST_CIVIL,\n    TAB_CLIENTE.NUM_CELULAR,\n    TAB_CLIENTE.DTA_ALTERACAO,\n    TAB_CLIENTE.DES_OBSERVACAO,\n    TAB_CLIENTE.DES_COMPLEMENTO,\n    TAB_CLIENTE.DES_EMAIL,\n    TAB_CLIENTE.DES_FANTASIA,\n    TAB_CLIENTE.DTA_NASCIMENTO,\n    TAB_CLIENTE.DES_PAI,\n    TAB_CLIENTE.DES_MAE,\n    TAB_CLIENTE.DES_CONJUGE,\n    TAB_CLIENTE.NUM_CPF_CONJUGE,\n    TAB_CLIENTE.VAL_DEB_CONV,\n    TAB_LOJA_CLIENTE.INATIVO,\n    TAB_CLIENTE.DES_MATRICULA,\n    TAB_CLIENTE.NUM_CGC_ASSOCIADO,\n    TAB_CLIENTE.FLG_PROD_RURAL,\n    TAB_CLIENTE.COD_STATUS_PDV_CONV,\n    TAB_CLIENTE.FLG_ENVIA_CODIGO,\n    TAB_CLIENTE.DTA_NASC_CONJUGE,\n    TAB_CLIENTE.COD_CLASSIF\nFROM TAB_CLIENTE\nINNER JOIN TAB_LOJA_CLIENTE\nON TAB_LOJA_CLIENTE.COD_CLIENTE = TAB_CLIENTE.COD_CLIENTE\nINNER JOIN TAB_CIDADE\nON TAB_CIDADE.COD_CIDADE = TAB_CLIENTE.COD_CIDADE;\n"