export default "SELECT \nTAB_SECAO.COD_SECAO,\nTAB_SECAO.DES_SECAO,\nTAB_GRUPO.COD_GRUPO,\nTAB_GRUPO.DES_GRUPO,\n--TAB_CENTRO_CUSTO.NUM_CENTRO_CUSTO,\n--TAB_PLANO_CONTA.CONTA_REDUZIDA AS CONTA_REDUZIDA_CTB, \nTAB_SUBGRUPO.COD_SUB_GRUPO,\nTAB_SUBGRUPO.DES_SUB_GRUPO \nFROM \nTAB_SECAO, \nTAB_GRUPO, \nTAB_SUBGRUPO   \nLEFT JOIN TAB_CENTRO_CUSTO ON \n  TAB_SUBGRUPO.COD_CENTRO_CUSTO = TAB_CENTRO_CUSTO.COD_CENTRO_CUSTO \nLEFT JOIN TAB_PLANO_CONTA ON \n  TAB_SUBGRUPO.COD_CONTA_CTB_RESULT = TAB_PLANO_CONTA.COD_CONTA \nWHERE \nTAB_SECAO.COD_SECAO = TAB_GRUPO.COD_SECAO \nAND \nTAB_SECAO.COD_SECAO = TAB_SUBGRUPO.COD_SECAO \nAND \nTAB_GRUPO.COD_GRUPO = TAB_SUBGRUPO.COD_GRUPO \nORDER BY TAB_SECAO.COD_SECAO, TAB_GRUPO.COD_GRUPO, TAB_SUBGRUPO.COD_SUB_GRUPO;\n"